const crypto = require('crypto');
const secret = String($env.DROP_RATE_AUTOMATION_COMMAND_SECRET || '').trim();
const controlUrl = String($env.DROP_RATE_API_AUTOMATION_CONTROL_URL || '').trim();
if (secret.length < 32) throw new Error('artwork_command_secret_not_configured');
if (!/\/api\/v1\/automation\/control\/receipt$/.test(controlUrl)) throw new Error('artwork_control_url_invalid');
const executionId = String($execution.id || '').trim();
if (!executionId) throw new Error('missing_artwork_execution_id');
const body = JSON.stringify({schema_version:1,action:'REFRESH_ELIGIBLE_ARTWORK',execution_id:executionId.slice(0,120),occurred_at:new Date().toISOString(),canonical_limit:3,reference_limit:10});
const timestamp = String(Math.floor(Date.now()/1000));
const signature = 'sha256=' + crypto.createHmac('sha256',secret).update(timestamp + '.' + body,'utf8').digest('hex');
return [{json:{artwork_url:controlUrl.replace(/\/control\/receipt$/, '/commands/storage/refresh-eligible-artwork'),artwork_body:body,artwork_timestamp:timestamp,artwork_signature:signature,artwork_execution_id:executionId.slice(0,120)}}];

const response = $input.first().json || {};
const status = Number(response.statusCode || 0);
if (status < 200 || status >= 300) throw new Error('artwork_refresh_http_' + status);
const body = response.body || {};
if (body.accepted !== true || typeof body.execution_id !== 'string') throw new Error('artwork_refresh_receipt_invalid');
if (body.new_game_metadata_promoted !== false) throw new Error('unexpected_artwork_publication_scope');
if (body.scope !== 'RIGHTS_APPROVED_CANONICAL_AND_LEGACY_REFERENCE_ONLY') throw new Error('unexpected_artwork_scope');
if (body.status === 'DEFERRED_CAPACITY') {
  if (typeof body.capacity_reason !== 'string' || body.canonical !== null || body.reference !== null) throw new Error('capacity_defer_receipt_invalid');
  return [{json:{execution_id:body.execution_id,status:body.status,capacity_reason:body.capacity_reason}}];
}
if (body.status !== 'COMPLETED') throw new Error('artwork_refresh_not_completed');
const canonical = body.canonical;
if (!canonical || typeof canonical.mirrored !== 'number' || Number(canonical.failed) !== 0 || canonical.mirrored < 0) throw new Error('approved_media_receipt_invalid');
if (body.reference_status === 'REFERENCE_ONLY_CACHE_VERIFIED') {
  if (!body.reference || typeof body.reference.mirrored !== 'number' || Number(body.reference.failed) !== 0) throw new Error('reference_media_receipt_invalid');
} else if (body.reference_status !== 'DISABLED_BY_BACKEND_POLICY' || body.reference !== null) throw new Error('reference_scope_not_verified');
return [{json:{execution_id:body.execution_id,status:'VERIFIED_ELIGIBLE_MEDIA_BATCH',canonical_mirrored:canonical.mirrored,reference_mirrored:body.reference?.mirrored || 0,canonical_remaining:canonical.remaining_possible,reference_remaining:body.reference?.remaining_possible || false,reference_status:body.reference_status}}];
